WITH filtered AS (SELECT *, DATEDIFF(CURRENT_DATE(), starts_on) AS days_since_starts_on FROM promotions WHERE ends_on >= DATE '2023-06-22' AND YEAR(ends_on) >= 2025) SELECT id, channel, promo_code, starts_on, ends_on, discount_pct, days_since_starts_on, AVG(days_since_starts_on) OVER (PARTITION BY channel) AS channel_avg_days_since_starts_on, NTILE(4) OVER (PARTITION BY promo_code ORDER BY days_since_starts_on, id) AS days_since_starts_on_bucket, LAST_VALUE(days_since_starts_on, TRUE) OVER (PARTITION BY channel, promo_code ORDER BY ends_on, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_days_since_starts_on, NTILE(3) OVER (PARTITION BY channel ORDER BY discount_pct, id) AS discount_pct_bucket FROM filtered
